const EVENT = { new_lead: 'listing.inquiry', lead: 'listing.inquiry', showing_scheduled: 'showing.scheduled', showing_completed: 'showing.completed' };
return $input.all().flatMap(({ json }) => {
  const b = json.body ?? json; // the Webhook node puts the POST body under .body
  const event = EVENT[b.event_type ?? b.type];
  if (!event) return []; // other notifications are not Mortar's business
  const payload = {
    id: `${b.event_type ?? b.type}-${b.id ?? b.showing_id ?? b.lead_id}`,
    event,
    source: 'showmojo',
    listingId: String(b.listing_id ?? b.listing?.id ?? ''),
    prospect: { name: b.name ?? b.prospect?.name, phone: b.phone ?? b.prospect?.phone, email: b.email ?? b.prospect?.email },
    message: b.message ?? b.comments ?? '',
    showingId: b.showing_id ?? null,
    startsAt: b.showing_time ?? b.starts_at ?? null,
    occurredAt: b.created_at ?? new Date().toISOString(),
  };
  return [{ json: { payload: JSON.stringify(payload) } }];
});
